WITH src AS(SELECT x.*,md5('fbmn:soctrang-old:wave02:'||x.source_key) dg FROM jsonb_to_recordset('[{"district":"Huyện Long Phú","name":"VPP Kiến Quốc","address_line":"Khu vực xã Trường Khánh cũ, huyện Long Phú (Plus Code M2H5+6Q5)","category":"van_phong_pham","phone":"02993844710","tax_code":null,"source_key":"gmap:ChIJhxri5phPoDERyl3GkH1qilk","source_url":"https://www.google.com/maps/search/?api=1&query=VPP%20Ki%E1%BA%BFn%20Qu%E1%BB%91c%20Khu%20v%E1%BB%B1c%20x%C3%A3%20Tr%C6%B0%E1%BB%9Dng%20Kh%C3%A1nh%20c%C5%A9%2C%20huy%E1%BB%87n%20Long%20Ph%C3%BA%20(Plus%20Code%20M2H5%2B6Q5)%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJhxri5phPoDERyl3GkH1qilk","verification_note":"Nguồn bản đồ ghi Trường Khánh mới, khu vực thuộc Long Phú cũ."},{"district":"Huyện Long Phú","name":"VPP Minh Phúc","address_line":"506 QL Nam Sông Hậu, thị trấn Đại Ngãi cũ, huyện Long Phú","category":"van_phong_pham","phone":"02993712158","tax_code":null,"source_key":"gmap:ChIJPf3fHXxGoDERj_QjpQwd8ig","source_url":"https://www.google.com/maps/search/?api=1&query=VPP%20Minh%20Ph%C3%BAc%20506%20QL%20Nam%20S%C3%B4ng%20H%E1%BA%ADu%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20%C4%90%E1%BA%A1i%20Ng%C3%A3i%20c%C5%A9%2C%20huy%E1%BB%87n%20Long%20Ph%C3%BA%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJPf3fHXxGoDERj_QjpQwd8ig","verification_note":"Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."},{"district":"Huyện Long Phú","name":"VPP Biển báo, Thiết bị văn phòng Hòa Hưng","address_line":"Ấp Hòa Hưng, khu vực Đại Ngãi cũ, huyện Long Phú","category":"van_phong_pham","phone":"0907019853","tax_code":null,"source_key":"gmap:ChIJTS0okntGoDER7d8TCt8VMho","source_url":"https://www.google.com/maps/search/?api=1&query=VPP%20Bi%E1%BB%83n%20b%C3%A1o%2C%20Thi%E1%BA%BFt%20b%E1%BB%8B%20v%C4%83n%20ph%C3%B2ng%20H%C3%B2a%20H%C6%B0ng%20%E1%BA%A4p%20H%C3%B2a%20H%C6%B0ng%2C%20khu%20v%E1%BB%B1c%20%C4%90%E1%BA%A1i%20Ng%C3%A3i%20c%C5%A9%2C%20huy%E1%BB%87n%20Long%20Ph%C3%BA%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJTS0okntGoDER7d8TCt8VMho","verification_note":"Có biển báo/thiết bị, cần xác minh hàng giấy bút."},{"district":"Huyện Mỹ Xuyên","name":"Hiệu sách Mỹ Ngọc","address_line":"Đường Trưng Vương, thị trấn Mỹ Xuyên cũ (HX6Q+2RR), huyện Mỹ Xuyên","category":"nha_sach","phone":"02993851766","tax_code":null,"source_key":"gmap:ChIJq4KVRXJNoDERrJh9exbsuqg","source_url":"https://www.google.com/maps/search/?api=1&query=Hi%E1%BB%87u%20s%C3%A1ch%20M%E1%BB%B9%20Ng%E1%BB%8Dc%20%C4%90%C6%B0%E1%BB%9Dng%20Tr%C6%B0ng%20V%C6%B0%C6%A1ng%2C%20th%E1%BB%8B%20tr%E1%BA%A5n%20M%E1%BB%B9%20Xuy%C3%AAn%20c%C5%A9%20(HX6Q%2B2RR)%2C%20huy%E1%BB%87n%20M%E1%BB%B9%20Xuy%C3%AAn%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJq4KVRXJNoDERrJh9exbsuqg","verification_note":"Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."},{"district":"Thị xã Ngã Năm","name":"Nhà sách Ngã Năm 2","address_line":"Nguyễn Văn Linh, khóm 3, TX Ngã Năm cũ","category":"nha_sach","phone":"0865452578","tax_code":null,"source_key":"gmap:ChIJ9zWJRQD9oDERTn8Us_YPgRU","source_url":"https://www.google.com/maps/search/?api=1&query=Nh%C3%A0%20s%C3%A1ch%20Ng%C3%A3%20N%C4%83m%202%20Nguy%E1%BB%85n%20V%C4%83n%20Linh%2C%20kh%C3%B3m%203%2C%20TX%20Ng%C3%A3%20N%C4%83m%20c%C5%A9%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJ9zWJRQD9oDERTn8Us_YPgRU","verification_note":"Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."},{"district":"Thị xã Ngã Năm","name":"Siêu thị nhà sách Việt Tư","address_line":"102 Mai Thanh Thế, khóm 1, TX Ngã Năm cũ","category":"nha_sach","phone":"0903003499","tax_code":null,"source_key":"gmap:ChIJvw-lbAD9oDERemr_9rJpEUQ","source_url":"https://www.google.com/maps/search/?api=1&query=Si%C3%AAu%20th%E1%BB%8B%20nh%C3%A0%20s%C3%A1ch%20Vi%E1%BB%87t%20T%C6%B0%20102%20Mai%20Thanh%20Th%E1%BA%BF%2C%20kh%C3%B3m%201%2C%20TX%20Ng%C3%A3%20N%C4%83m%20c%C5%A9%20S%C3%B3c%20Tr%C4%83ng&query_place_id=ChIJvw-lbAD9oDERemr_9rJpEUQ","verification_note":"Nguồn địa điểm bản đồ, chưa Sales ghé hoặc xác minh cửa hàng còn hoạt động năm 2026."}]'::jsonb) AS x(
 district text,name text,address_line text,category text,phone text,tax_code text,source_key text,source_url text,verification_note text)),
 ins AS(INSERT INTO public.field_prospects(id,area_visit_id,owner_sub,name,address_line,province,district,category,phone,tax_code,note,status,source_kind,research_source_key,research_source_url,research_batch)
 SELECT (substr(s.dg,1,8)||'-'||substr(s.dg,9,4)||'-5'||substr(s.dg,14,3)||'-8'||substr(s.dg,18,3)||'-'||substr(s.dg,21,12))::uuid,
 NULL,'ef943de4-18f7-49ef-8340-eefb18855534',s.name,s.address_line,'Sóc Trăng',s.district,s.category,s.phone,s.tax_code,
 'Nguồn công khai 21/11/2026; CHƯA GHÉ; GPS chưa xác minh; tình trạng bán lẻ chưa xác minh. '||s.verification_note||' Nguồn: '||s.source_url,
 'new','manual',s.source_key,s.source_url,'2026-11-21-soc-trang-old-wave-02'
 FROM src s WHERE s.district IN ('Huyện Cù Lao Dung','Huyện Long Phú','Huyện Mỹ Xuyên','Thị xã Ngã Năm') AND s.source_url LIKE 'https://%'
 AND NOT EXISTS(SELECT 1 FROM customers c WHERE c.province='Sóc Trăng' AND c.district=s.district AND
 (lower(trim(c.name))=lower(trim(s.name)) OR (c.phone IS NOT NULL AND s.phone IS NOT NULL AND c.phone=s.phone)))
 AND NOT EXISTS(SELECT 1 FROM field_prospects p WHERE p.province='Sóc Trăng' AND p.district=s.district AND
 (p.research_source_key=s.source_key OR (lower(trim(p.name))=lower(trim(s.name)) AND lower(trim(p.address_line))=lower(trim(s.address_line)))
 OR (p.phone IS NOT NULL AND s.phone IS NOT NULL AND p.phone=s.phone) OR (p.tax_code IS NOT NULL AND s.tax_code IS NOT NULL AND p.tax_code=s.tax_code)))
 ON CONFLICT(research_source_key) WHERE research_source_key IS NOT NULL DO NOTHING RETURNING district,category,phone)
 SELECT district,count(*)::int inserted,count(*) FILTER(WHERE category='nha_sach')::int bookstores FROM ins GROUP BY district ORDER BY district;